40: /**
41:  * Recursively remove a directory and its contents.
42:  *
43:  * @param {string} dirPath path of directory to remove
44:  * @param {Function} callback
45:  * @private
46:  */
47: function rimraf(dirPath, callback) {
48:   return fs.rm(dirPath, { recursive: true }, callback);
49: }
