61: /**
62:  * Gets a temporary file name.
63:  *
64:  * @param {(Options|tmpNameCallback)} options options or callback
65:  * @param {?tmpNameCallback} callback the callback function
66:  */
67: function tmpName(options, callback) {
68:   const args = _parseArguments(options, callback),
69:     opts = args[0],
70:     cb = args[1];
71: 
72:   _assertAndSanitizeOptions(opts, function (err, sanitizedOptions) {
73:     if (err) return cb(err);
74: 
75:     let tries = sanitizedOptions.tries;
76:     (function _getUniqueName() {
77:       try {
78:         const name = _generateTmpName(sanitizedOptions);
79: 
80:         // check whether the path exists then retry if needed
81:         fs.stat(name, function (err) {
82:           /* istanbul ignore else */
83:           if (!err) {
84:             /* istanbul ignore else */
85:             if (tries-- > 0) return _getUniqueName();
86: 
87:             return cb(new Error('Could not get a unique tmp filename, max tries reached ' + name));
88:           }
89: 
90:           cb(null, name);
91:         });
92:       } catch (err) {
93:         cb(err);
94:       }
95:     })();
96:   });
97: }
98: 
99: /**
100:  * Synchronous version of tmpName.
101:  *
102:  * @param {Object} options
103:  * @returns {string} the generated random name
104:  * @throws {Error} if the options are invalid or could not generate a filename
105:  */
106: function tmpNameSync(options) {
107:   const args = _parseArguments(options),
108:     opts = args[0];
109: 
110:   const sanitizedOptions = _assertAndSanitizeOptionsSync(opts);
111: 
112:   let tries = sanitizedOptions.tries;
113:   do {
114:     const name = _generateTmpName(sanitizedOptions);
115:     try {
116:       fs.statSync(name);
117:     } catch (e) {
118:       return name;
119:     }
120:   } while (tries-- > 0);
121: 
122:   throw new Error('Could not get a unique tmp filename, max tries reached');
123: }
