161: /**
162:  * Synchronous version of file.
163:  *
164:  * @param {Options} options
165:  * @returns {FileSyncObject} object consists of name, fd and removeCallback
166:  * @throws {Error} if cannot create a file
167:  */
168: function fileSync(options) {
169:   const args = _parseArguments(options),
170:     opts = args[0];
171: 
172:   const discardOrDetachDescriptor = opts.discardDescriptor || opts.detachDescriptor;
173:   const name = tmpNameSync(opts);
174:   let fd = fs.openSync(name, CREATE_FLAGS, opts.mode || FILE_MODE);
175:   /* istanbul ignore else */
176:   if (opts.discardDescriptor) {
177:     fs.closeSync(fd);
178:     fd = undefined;
179:   }
180: 
181:   return {
182:     name: name,
183:     fd: fd,
184:     removeCallback: _prepareTmpFileRemoveCallback(name, discardOrDetachDescriptor ? -1 : fd, opts, true)
185:   };
186: }
