188: /**
189:  * Creates a temporary directory.
190:  *
191:  * @param {(Options|dirCallback)} options the options or the callback function
192:  * @param {?dirCallback} callback
193:  */
194: function dir(options, callback) {
195:   const args = _parseArguments(options, callback),
196:     opts = args[0],
197:     cb = args[1];
198: 
199:   // gets a temporary filename
200:   tmpName(opts, function _tmpNameCreated(err, name) {
201:     /* istanbul ignore else */
202:     if (err) return cb(err);
203: 
204:     // create the directory
205:     fs.mkdir(name, opts.mode || DIR_MODE, function _dirCreated(err) {
206:       /* istanbul ignore else */
207:       if (err) return cb(err);
208: 
209:       cb(null, name, _prepareTmpDirRemoveCallback(name, opts, false));
210:     });
211:   });
212: }
