214: /**
215:  * Synchronous version of dir.
216:  *
217:  * @param {Options} options
218:  * @returns {DirSyncObject} object consists of name and removeCallback
219:  * @throws {Error} if it cannot create a directory
220:  */
221: function dirSync(options) {
222:   const args = _parseArguments(options),
223:     opts = args[0];
224: 
225:   const name = tmpNameSync(opts);
226:   fs.mkdirSync(name, opts.mode || DIR_MODE);
227: 
228:   return {
229:     name: name,
230:     removeCallback: _prepareTmpDirRemoveCallback(name, opts, true)
231:   };
232: }
