234: /**
235:  * Removes files asynchronously.
236:  *
237:  * @param {Object} fdPath
238:  * @param {Function} next
239:  * @private
240:  */
241: function _removeFileAsync(fdPath, next) {
242:   const _handler = function (err) {
243:     if (err && !_isENOENT(err)) {
244:       // reraise any unanticipated error
245:       return next(err);
246:     }
247:     next();
248:   };
249: 
250:   if (0 <= fdPath[0])
251:     fs.close(fdPath[0], function () {
252:       fs.unlink(fdPath[1], _handler);
253:     });
254:   else fs.unlink(fdPath[1], _handler);
255: }
256: 
257: /**
258:  * Removes files synchronously.
259:  *
260:  * @param {Object} fdPath
261:  * @private
262:  */
263: function _removeFileSync(fdPath) {
264:   let rethrownException = null;
265:   try {
266:     if (0 <= fdPath[0]) fs.closeSync(fdPath[0]);
267:   } catch (e) {
268:     // reraise any unanticipated error
269:     if (!_isEBADF(e) && !_isENOENT(e)) throw e;
270:   } finally {
271:     try {
272:       fs.unlinkSync(fdPath[1]);
273:     } catch (e) {
274:       // reraise any unanticipated error
275:       if (!_isENOENT(e)) rethrownException = e;
276:     }
277:   }
278:   if (rethrownException !== null) {
279:     throw rethrownException;
280:   }
281: }
