409: /**
410:  * Checks whether the `obj` parameter is defined or not.
411:  *
412:  * @param {Object} obj
413:  * @returns {boolean} true if the object is undefined
414:  * @private
415:  */
416: function _isUndefined(obj) {
417:   return typeof obj === 'undefined';
418: }
