420: /**
421:  * Parses the function arguments.
422:  *
423:  * This function helps to have optional arguments.
424:  *
425:  * @param {(Options|null|undefined|Function)} options
426:  * @param {?Function} callback
427:  * @returns {Array} parsed arguments
428:  * @private
429:  */
430: function _parseArguments(options, callback) {
431:   /* istanbul ignore else */
432:   if (typeof options === 'function') {
433:     return [{}, options];
434:   }
435: 
436:   /* istanbul ignore else */
437:   if (_isUndefined(options)) {
438:     return [{}, callback];
439:   }
440: 
441:   // copy options so we do not leak the changes we make internally
442:   const actualOptions = {};
443:   for (const key of Object.getOwnPropertyNames(options)) {
444:     actualOptions[key] = options[key];
445:   }
446: 
447:   return [actualOptions, callback];
448: }
