450: /**
451:  * Resolve the specified path name in respect to tmpDir.
452:  *
453:  * The specified name might include relative path components, e.g. ../
454:  * so we need to resolve in order to be sure that is is located inside tmpDir
455:  *
456:  * @private
457:  */
458: function _resolvePath(name, tmpDir, cb) {
459:   const pathToResolve = path.isAbsolute(name) ? name : path.join(tmpDir, name);
460: 
461:   fs.stat(pathToResolve, function (err) {
462:     if (err) {
463:       fs.realpath(path.dirname(pathToResolve), function (err, parentDir) {
464:         if (err) return cb(err);
465: 
466:         cb(null, path.join(parentDir, path.basename(pathToResolve)));
467:       });
468:     } else {
469:       fs.realpath(pathToResolve, cb);
470:     }
471:   });
472: }
