474: /**
475:  * Resolve the specified path name in respect to tmpDir.
476:  *
477:  * The specified name might include relative path components, e.g. ../
478:  * so we need to resolve in order to be sure that is is located inside tmpDir
479:  *
480:  * @private
481:  */
482: function _resolvePathSync(name, tmpDir) {
483:   const pathToResolve = path.isAbsolute(name) ? name : path.join(tmpDir, name);
484: 
485:   try {
486:     fs.statSync(pathToResolve);
487:     return fs.realpathSync(pathToResolve);
488:   } catch (_err) {
489:     const parentDir = fs.realpathSync(path.dirname(pathToResolve));
490: 
491:     return path.join(parentDir, path.basename(pathToResolve));
492:   }
493: }
