495: /**
496:  * Generates a new temporary name.
497:  *
498:  * @param {Object} opts
499:  * @returns {string} the new random name according to opts
500:  * @private
501:  */
502: function _generateTmpName(opts) {
503:   const tmpDir = opts.tmpdir;
504: 
505:   /* istanbul ignore else */
506:   if (!_isUndefined(opts.name)) {
507:     return path.join(tmpDir, opts.dir, opts.name);
508:   }
509: 
510:   /* istanbul ignore else */
511:   if (!_isUndefined(opts.template)) {
512:     return path.join(tmpDir, opts.dir, opts.template).replace(TEMPLATE_PATTERN, _randomChars(6));
513:   }
514: 
515:   // prefix and postfix
516:   const name = [
517:     opts.prefix ? opts.prefix : 'tmp',
518:     '-',
519:     process.pid,
520:     '-',
521:     _randomChars(12),
522:     opts.postfix ? '-' + opts.postfix : ''
523:   ].join('');
524: 
525:   return path.join(tmpDir, opts.dir, name);
526: }
