528: /**
529:  * Check the prefix, postfix, and template options.
530:  *
531:  * Rejects non-string inputs so that a non-string `.includes('..')` cannot evade
532:  * the substring check (e.g. an Array whose `.includes('..')` is element-wise,
533:  * or a duck-typed object with a custom `.includes`), and so that the value is
534:  * not later coerced to a string with traversal sequences via `Array.prototype.join`
535:  * or `path.join`.
536:  *
537:  * @private
538:  */
539: function _assertPath(option, value) {
540:   if (typeof value !== 'string') {
541:     throw new Error(`${option} option must be a string, got "${typeof value}".`);
542:   }
543: 
544:   if (value.includes("..")) {
545:     throw new Error("Relative value not allowed");
546:   }
547: 
548:   return value;
549: }
