551: /**
552:  * Asserts and sanitizes the basic options.
553:  *
554:  * @private
555:  */
556: function _assertOptionsBase(options) {
557:   if (!_isUndefined(options.name)) {
558:     const name = options.name;
559: 
560:     // assert that name is not absolute and does not contain a path
561:     if (path.isAbsolute(name)) throw new Error(`name option must not contain an absolute path, found "${name}".`);
562: 
563:     // must not fail on valid .<name> or ..<name> or similar such constructs
564:     const basename = path.basename(name);
565:     if (basename === '..' || basename === '.' || basename !== name) {
566:       throw new Error(`name option must not contain a path, found "${name}".`);
567:     }
568:   }
569: 
570:   /* istanbul ignore else */
571:   if (!_isUndefined(options.template)) {
572:     if (typeof options.template !== 'string') {
573:       throw new Error(`template option must be a string, got "${typeof options.template}".`);
574:     }
575:     if (!options.template.match(TEMPLATE_PATTERN)) {
576:       throw new Error(`Invalid template, found "${options.template}".`);
577:     }
578:   }
